/**
 * Secure Runtime Alpha 4741-4820 — Phase D: Pinned Artifact Manifest.
 *
 * A versioned record of ONLY safe, public facts about the generated
 * WASM artifact the production Desktop path is permitted to load. It
 * carries NO secret, NO seed, NO key — only a schema version, the Rust
 * crate build identity, the two generated filenames, the artifact's
 * cryptographic hash, the reviewed capability profile / allowed export
 * set, an optional build timestamp, and a compatibility version. It is
 * GENERATED by the accepted build pipeline (Phase E,
 * `scripts/generate_wasm_artifact_manifest.mjs`) into the gitignored
 * `pkg/` output — never hand-edited, never committed — and VERIFIED
 * before the artifact is loaded. Filenames are never trusted alone: the
 * hash is recomputed from the real bytes at verify time.
 *
 * NO remote fetch of any kind: the manifest and the artifact both live
 * on the local, packaged filesystem.
 */

import { sha256 } from "@noble/hashes/sha2.js";
import { bytesToHex } from "@noble/hashes/utils.js";

/** The one reviewed capability profile the production Desktop path accepts. */
export const FEDOS_PRODUCTION_MASTER_SEED_CAPABILITY_PROFILE = "desktop-master-seed-v1" as const;

/** The current manifest schema version. */
export const FEDOS_PRODUCTION_WASM_MANIFEST_SCHEMA_VERSION = 1 as const;

/** The compatibility version the production loader is built to accept. */
export const FEDOS_PRODUCTION_WASM_COMPATIBILITY_VERSION = 1 as const;

/**
 * The exact, closed set of module-level exports the production
 * Desktop Master Seed facade is permitted to touch. Anything beyond
 * these is out of scope for this capability profile — the facade never
 * reads, enumerates, or returns any other export, and never returns the
 * module namespace itself.
 */
export const FEDOS_PRODUCTION_MASTER_SEED_ALLOWED_EXPORTS: readonly string[] = Object.freeze([
  "FedosMasterSeedAuthority",
  "initSync",
]);

export interface FedosProductionWasmArtifactManifestV1 {
  readonly schemaVersion: 1;
  readonly crateName: string;
  readonly crateVersion: string;
  readonly wasmFilename: string;
  readonly jsGlueFilename: string;
  /** Lowercase hex SHA-256 of the exact `wasmFilename` bytes. */
  readonly wasmSha256Hex: string;
  /** The reviewed capability profile this artifact was pinned for. */
  readonly capabilityProfile: string;
  /** The exact module-level exports the capability profile permits. */
  readonly allowedExports: readonly string[];
  /** A monotonically-checked compatibility version. */
  readonly compatibilityVersion: number;
  /** Optional, non-secret build metadata (deterministic-where-possible). */
  readonly generatedAt?: string;
}

/** Closed vocabulary — never a bare boolean. */
export type FedosManifestVerificationResult =
  | "ok"
  | "manifest-malformed"
  | "schema-unsupported"
  | "version-incompatible"
  | "capability-not-allowed"
  | "hash-mismatch"
  | "export-missing";

/** Recompute the lowercase-hex SHA-256 of the given artifact bytes. */
export function fedosWasmArtifactSha256Hex(wasmBytes: Uint8Array): string {
  return bytesToHex(sha256(wasmBytes));
}

/**
 * Structural validation of a parsed manifest object. Returns the typed
 * manifest on success, or `null` (never throws) on any malformed shape.
 */
export function parseFedosProductionWasmArtifactManifest(
  candidate: unknown,
): FedosProductionWasmArtifactManifestV1 | null {
  if (typeof candidate !== "object" || candidate === null) return null;
  const m = candidate as Record<string, unknown>;
  const stringField = (v: unknown): v is string => typeof v === "string" && v.length > 0;
  if (m.schemaVersion !== 1) return null;
  if (!stringField(m.crateName)) return null;
  if (!stringField(m.crateVersion)) return null;
  if (!stringField(m.wasmFilename)) return null;
  if (!stringField(m.jsGlueFilename)) return null;
  if (!stringField(m.wasmSha256Hex) || !/^[0-9a-f]{64}$/.test(m.wasmSha256Hex)) return null;
  if (!stringField(m.capabilityProfile)) return null;
  if (!Array.isArray(m.allowedExports) || !m.allowedExports.every((e) => typeof e === "string")) return null;
  if (typeof m.compatibilityVersion !== "number") return null;
  if (m.generatedAt !== undefined && typeof m.generatedAt !== "string") return null;
  return Object.freeze({
    schemaVersion: 1,
    crateName: m.crateName,
    crateVersion: m.crateVersion,
    wasmFilename: m.wasmFilename,
    jsGlueFilename: m.jsGlueFilename,
    wasmSha256Hex: m.wasmSha256Hex,
    capabilityProfile: m.capabilityProfile,
    allowedExports: Object.freeze([...(m.allowedExports as string[])]),
    compatibilityVersion: m.compatibilityVersion,
    generatedAt: m.generatedAt as string | undefined,
  });
}

/**
 * Verify a manifest against the reviewed profile and the REAL artifact
 * bytes. `presentExportNames` is the set of module-level export names
 * actually observed on the imported JS glue — every allowed export the
 * profile requires must be present. The hash is recomputed here from
 * `wasmBytes`; the manifest's own stored hash is never trusted alone.
 */
export function verifyFedosProductionWasmArtifactManifest(
  manifest: FedosProductionWasmArtifactManifestV1 | null,
  wasmBytes: Uint8Array,
  presentExportNames: readonly string[],
): FedosManifestVerificationResult {
  if (manifest === null) return "manifest-malformed";
  if (manifest.schemaVersion !== FEDOS_PRODUCTION_WASM_MANIFEST_SCHEMA_VERSION) return "schema-unsupported";
  if (manifest.compatibilityVersion !== FEDOS_PRODUCTION_WASM_COMPATIBILITY_VERSION) return "version-incompatible";
  if (manifest.capabilityProfile !== FEDOS_PRODUCTION_MASTER_SEED_CAPABILITY_PROFILE) return "capability-not-allowed";
  // The manifest's allowed export set must be exactly the reviewed set.
  const wanted = [...FEDOS_PRODUCTION_MASTER_SEED_ALLOWED_EXPORTS].sort();
  const declared = [...manifest.allowedExports].sort();
  if (wanted.length !== declared.length || wanted.some((e, i) => e !== declared[i])) {
    return "capability-not-allowed";
  }
  // The real bytes must hash to the pinned value (recomputed, not trusted).
  if (fedosWasmArtifactSha256Hex(wasmBytes) !== manifest.wasmSha256Hex) return "hash-mismatch";
  // Every reviewed export must actually be present on the glue module.
  const present = new Set(presentExportNames);
  for (const name of FEDOS_PRODUCTION_MASTER_SEED_ALLOWED_EXPORTS) {
    if (!present.has(name)) return "export-missing";
  }
  return "ok";
}
